import type {Attempt,CourseContent,Flashcard,Question,Topic,UserState} from './types.js';
import {initialState,allCards,allQuestions,attemptStats,calendarStreak,localDayKey,marketEquilibrium,dueCards,examinationResult,newCards,nextReview,pickQuestions,planReview,recordedAttempt,topicProgress} from './engine.js';
import {backupJson,loadState,parseBackup,saveState} from './store.js';
import {adaptiveQuestions,dueForecast,studySummary,unresolvedMistakes,weakTopics} from './coach.js';
import {CALC_SKILLS,calcSkillProgress,generateCalcProblem,gradeCalcProblem,suggestedCalcSkill} from './calculations.js';
import type {CalcProblem,CalcSkillId} from './calculations.js';

type View = 'math'|'home'|'topics'|'lesson'|'review'|'practice'|'exam'|'glossary'|'lab'|'stats'|'settings'|'coach'|'mistakes';
type QEntry = {topic:Topic;question:Question};
type CEntry = {topic:Topic;card:Flashcard};
type QuizSession={kind:'practice'|'exam';entries:QEntry[];index:number;chosen:number|null;results:Attempt[];done:boolean;topicId:string|null};
type CardSession={entries:CEntry[];index:number;revealed:boolean;done:boolean;grades:Record<string,number>};
const esc=(value:unknown):string=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[ch]??ch));
const dateLabel=(v:string)=>new Intl.DateTimeFormat('cs-CZ',{day:'numeric',month:'short'}).format(new Date(v));
const icon=(name:string,size=20)=>{
 const paths:Record<string,string>={
  home:'<rect x="3" y="3" width="18" height="18" rx="4"/><path d="m8 13 4-4 4 4M12 9v9"/>',
  book:'<path d="M12 7v14m0-14C8 5 5 5 2 7v13c3-2 6-2 10 1m0-14c4-2 7-2 10 0v13c-3-2-6-2-10 1"/>',
  layers:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M8 8h8m-8 4h8m-8 4h4"/>',
  repeat:'<path d="m4 7 3-3 3 3M7 4v11a4 4 0 0 0 4 4h6m3-2-3 3-3-3m3 3V9a4 4 0 0 0-4-4H7"/>',
  target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
  search:'<circle cx="11" cy="11" r="7"/><path d="m16.5 16.5 5 5"/>',
  stats:'<path d="M4 20V9m5 11V4m5 16v-8m5 8V6"/>',
  settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M19 5l-2 2M7 17l-2 2"/>',
  arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
  check:'<path d="m4 12 5 5L20 6"/>',
  chevron:'<path d="m9 18 6-6-6-6"/>',
  brain:'<path d="M12 4c-2-2-6-1-6 3-3 0-4 4-2 6-1 4 2 7 5 6 1 2 4 1 4-1V5c1-2 5-3 6 0 3 0 4 4 2 6 2 3 0 7-3 7-2 3-5 1-6-1"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',
  spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z"/>',
  download:'<path d="M12 3v12m-5-5 5 5 5-5M4 18v3h16v-3"/>',
  upload:'<path d="M12 21V9m-5 5 5-5 5 5M4 6V3h16v3"/>',
  shield:'<path d="m12 2 8 4v6c0 5-3 8-8 10-5-2-8-5-8-10V6z"/>',
  moon:'<path d="M20 15a8 8 0 0 1-11-11 8 8 0 1 0 11 11z"/>',
  sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',
  alert:'<path d="m12 3 10 18H2zM12 9v5m0 3v.3"/>',
  play:'<path d="m7 4 12 8-12 8z"/>',
  menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',
  close:'<path d="M4 4l16 16M20 4 4 20"/>'};
 return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]??paths.layers}</svg>`;
};

export class MikroLab {
 readonly content:CourseContent; state:UserState; private mount:HTMLElement;
 private view:View='home';private topicId:string|null=null;private quiz:QuizSession|null=null;private review:CardSession|null=null;
 private mathProblem:CalcProblem|null=null;private mathChoice:CalcSkillId|'adaptive'='adaptive';private mathHinted=false;private mathResult:{value:number|null;valid:boolean;correct:boolean}|null=null;private mathInputError='';private challengeRevealed=false;private demandShift=0;private supplyShift=0;private graphModel:'goods'|'labor'='goods';private notice='';private sidebarOpen=false;
 constructor(mount:HTMLElement,content:CourseContent){this.mount=mount;this.content=content;this.state=loadState(content);
  document.addEventListener('click',e=>this.onClick(e));document.addEventListener('keydown',e=>this.onKey(e));document.addEventListener('input',e=>this.onInput(e));
  document.addEventListener('change',e=>this.onChange(e));window.addEventListener('online',()=>this.updateConnectivity());window.addEventListener('offline',()=>this.updateConnectivity());
  this.render();}
 private persist(){if(!saveState(this.state))this.notice='Pokrok se nepodařilo uložit. V nastavení si vytvoř zálohu.';}
 private topic(){return this.content.topics.find(t=>t.id===this.topicId)??this.content.topics[0];}
 private nav(view:View,id:string|null=null){this.view=view;this.topicId=id;this.sidebarOpen=false;this.notice='';this.challengeRevealed=false;this.render();window.scrollTo({top:0,behavior:'instant'});}
 private navItem(view:View,label:string,ico:string){return `<button type="button" class="nav-item ${this.view===view?'active':''}" data-action="nav" data-value="${view}">${icon(ico,19)}<span>${label}</span>${this.view===view?'<span class="nav-marker"></span>':''}</button>`;}
 private render(){document.documentElement.dataset.theme=this.state.preference;
  let content='';if(this.view==='math')content=this.mathTrainer();if(this.view==='home')content=this.home();if(this.view==='topics')content=this.topics();if(this.view==='lesson')content=this.lesson();if(this.view==='review')content=this.reviewScreen();if(this.view==='practice'||this.view==='exam')content=this.quizScreen();if(this.view==='glossary')content=this.glossary();if(this.view==='lab')content=this.lab();if(this.view==='stats')content=this.stats();if(this.view==='settings')content=this.settings();if(this.view==='coach')content=this.coach();if(this.view==='mistakes')content=this.mistakes();
  const today=new Intl.DateTimeFormat('cs-CZ',{weekday:'long',day:'numeric',month:'long'}).format(new Date());
  this.mount.innerHTML=`<div class="shell"><aside class="sidebar ${this.sidebarOpen?'expanded':''}">
   <div class="brand"><span class="brand-icon">${icon('brain',24)}</span><span><strong>MikroLab<span class="brand-dot">.</span></strong><small>MIKROEKONOMIE I / UTB</small></span></div>
   <div class="side-caption">VÝUKA</div>
   <nav aria-label="Hlavní navigace">${this.navItem('home','Přehled','home')}${this.navItem('topics','Kapitoly','book')}${this.navItem('review','Opakování','repeat')}${this.navItem('coach','Studijní plán','target')}${this.navItem('mistakes','Moje chyby','alert')}${this.navItem('math','Početní trenažér','stats')}${this.navItem('exam','Cvičný zápočet','target')}${this.navItem('glossary','Pojmy','layers')}${this.navItem('lab','Laboratoř grafů','stats')}</nav>
   <div class="side-caption second">MOJE STUDIUM</div>
   <nav>${this.navItem('stats','Statistiky','stats')}${this.navItem('settings','Nastavení','settings')}</nav>
   <div class="sidebar-bottom"><div class="status-light"></div><span>Ukládá se pouze v tomto zařízení</span></div>
  </aside><div class="main-column"><header class="topbar"><div class="topbar-left"><button type="button" class="mobile-menu icon-button" data-action="menu" aria-label="Otevřít nabídku">${icon('menu')}</button><span class="breadcrumb">MIKROLAB <span>/</span> ${esc(this.viewTitle())}</span></div><div class="topbar-right"><span class="topbar-date">${esc(today)}</span><span class="connection" id="connection">${navigator.onLine?'● Offline režim připraven':'● Bez připojení'}</span><span class="avatar">M</span></div></header>
  <main id="main-content" class="content">${this.notice?`<div class="notice" role="status">${esc(this.notice)}</div>`:''}${content}</main><footer class="footer">MikroLab 0.3 · ${esc(this.content.disclaimer)}</footer></div></div>`;
  this.updateConnectivity();}
 private updateConnectivity(){const el=document.querySelector('#connection');if(el)el.textContent=navigator.onLine?'● Připraveno i offline':'● Bez připojení';}
 private viewTitle(){return ({math:'Početní trenažér',home:'Přehled',topics:'Kapitoly',lesson:this.topicId?this.topic().title:'Výklad',review:'Opakování',practice:'Procvičování',exam:'Cvičný zápočet',glossary:'Pojmy',lab:'Laboratoř grafů',stats:'Statistiky',settings:'Nastavení',coach:'Studijní plán',mistakes:'Moje chyby'} as Record<View,string>)[this.view];}
 private button(text:string,action:string,kind='primary',value='',ico='arrow'){return `<button type="button" class="btn btn-${kind}" data-action="${action}" ${value?`data-value="${esc(value)}"`:''}>${esc(text)}${ico?icon(ico,18):''}</button>`;}
 private sectionHead(kicker:string,title:string,desc:string){return `<div class="page-heading"><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>`;}
 private progressbar(value:number){return `<div class="progress-track" role="progressbar" aria-valuenow="${Math.round(value)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${Math.max(0,Math.min(100,value))}%"></span></div>`;}
 private home(){const cards=allCards(this.content),studied=Object.keys(this.state.cards).length;
  const dueNow=dueCards(this.content,this.state).length;const stats=attemptStats(this.state.attempts),streak=calendarStreak(this.state);
  const visited=this.state.visitedTopics.length;const daily=planReview(this.content,this.state);
  const next=this.content.topics.find(t=>!this.state.visitedTopics.includes(t.id))??this.content.topics[0];
  return `<section class="welcome"><div class="welcome-copy"><div class="eyebrow"><span class="live-dot"></span> TVOJE STUDIJNÍ CENTRUM</div><h1>Rozumět. Procvičit.<br/><em>Opravdu umět.</em></h1><p>Výklad s řešenými příklady, aktivní vybavování z paměti a opakování podle výsledků. Tvoje mikroekonomie na jednom místě.</p><div class="btn-row">${this.button(`Dnešní opakování${dueNow?` (${dueNow})`:''}`,'start-review','light','','repeat')}${this.button('Můj studijní plán','nav','ghost','coach','arrow')}</div></div><div class="hero-art" aria-hidden="true"><div class="orb orb-one"></div><div class="orb orb-two"></div><div class="hero-graphic">${icon('brain',104)}<span>LEARN / RECALL / REPEAT</span></div></div></section>
  ${this.homeSignal()}<section class="math-invite"><div><div class="eyebrow">NOVĚ / VÝPOČTY</div><h2>Vzorec nestačí znát. Musíš ho umět použít.</h2><p>12 typů příkladů s proměnlivými čísly, nápovědou a postupem řešení. Odpověď zadáváš sám.</p></div>${this.button('Otevřít početní trenažér','nav','primary','math','arrow')}</section><section class="stats-grid"><div class="stat"><span>Prostudované kapitoly</span><strong>${visited}<small> / ${this.content.topics.length}</small></strong><div class="metric-label">${Math.round(visited/this.content.topics.length*100)} % obsahu otevřeno</div></div><div class="stat"><span>Opakované pojmy</span><strong>${studied}<small> / ${cards.length}</small></strong><div class="metric-label">${dueNow} karet čeká na zopakování</div></div><div class="stat"><span>Úspěšnost odpovědí</span><strong>${stats.total?stats.percentage+' %':'—'}</strong><div class="metric-label">${stats.total} zodpovězených otázek</div></div><div class="stat"><span>Studijní série</span><strong>${streak}<small> dní</small></strong><div class="metric-label">Počítá se pouze aktivní studium</div></div></section>
  <div class="two-col"><section class="panel"><div class="panel-head"><div><div class="eyebrow">DALŠÍ KROK</div><h2>Co se dnes učit</h2></div><span class="muted-note">doporučený postup</span></div><div class="next-topic"><div class="sequence">${String(next.order).padStart(2,'0')}</div><div><span class="small-label">${this.state.visitedTopics.includes(next.id)?'Opakování kapitoly':'Další kapitola'}</span><h3>${esc(next.title)}</h3><p>${esc(next.blurb)}</p><div class="meta">${icon('clock',15)} ${next.minutes} minut · ${next.questions.length} otázek</div></div></div>${this.button('Otevřít kapitolu','topic','outline',next.id,'arrow')}${this.button('Cílený test slabších míst','start-adaptive','outline','','target')}</section>
   <section class="panel dark-panel"><div class="eyebrow">DENNÍ TRÉNINK</div><h2>${daily.length?`${daily.length} karet připraveno`:'Dnes máš splněno'}</h2><p>${daily.length?'Nejprve zopakuj starší pojmy a potom přidej nové. Odpověď si vybav před otočením karty.':'Žádné naplánované opakování. Můžeš začít další kapitolu nebo se otestovat.'}</p><div class="daily-ring" aria-hidden="true">${icon('repeat',42)}</div>${this.button('Spustit trénink','start-review','light','','arrow')}</section></div>
  <section class="module-section"><div class="panel-head"><div><div class="eyebrow">STUDIJNÍ PLÁN</div><h2>Procházej témata vlastním tempem</h2></div><button type="button" class="text-action" data-action="nav" data-value="topics">Všech ${this.content.topics.length} kapitol ${icon('arrow',17)}</button></div><div class="topic-mini-grid">${this.content.topics.slice(0,6).map(t=>this.topicMini(t)).join('')}</div></section>`;
 }
 private topicMini(t:Topic){const p=topicProgress(t,this.state);return `<button class="topic-mini" data-action="topic" data-value="${t.id}"><span class="topic-number">${String(t.order).padStart(2,'0')}</span><strong>${esc(t.title)}</strong><span>${p.finished?'Prostudováno':`${t.minutes} min · ${t.questions.length} otázek`}</span>${this.progressbar(p.finished?100:(p.reviewed/p.total*100))}</button>`;}
 private topics(){return `${this.sectionHead('STUDIJNÍ MAPA',`Všechny kapitoly`,`14 tematických celků vycházejících z vašich podkladů UTB. V každé kapitole najdeš výklad, příklad, pojmy a otázky.`)}<div class="filter-row"><span class="filter-chip active">Všechny kapitoly · ${this.content.topics.length}</span><span class="filter-chip">Semináře 1–13 + AI v praxi</span></div><div class="topic-grid">${this.content.topics.map(t=>{const p=topicProgress(t,this.state);return `<article class="topic-card"><div class="topic-top"><span class="topic-index">KAPITOLA ${String(t.order).padStart(2,'0')}</span><span class="topic-status ${p.finished?'finished':''}">${p.finished?'Prostudováno':'K výkladu'}</span></div><h2>${esc(t.title)}</h2><p>${esc(t.blurb)}</p><div class="topic-footer"><span>${icon('clock',16)} ${t.minutes} min · ${t.questions.length} úloh</span><button class="open-topic" data-action="topic" data-value="${t.id}" aria-label="Otevřít ${esc(t.title)}">${icon('arrow',18)}</button></div>${this.progressbar(p.finished?100:p.reviewed/p.total*100)}</article>`}).join('')}</div>`;}
 private lesson(){const t=this.topic(),p=topicProgress(t,this.state);return `<div class="lesson-top"><button class="backlink" data-action="nav" data-value="topics">← Zpět na kapitoly</button><span class="pill">SEM. ${t.order===14?'BONUS':t.order}</span></div><div class="lesson-hero"><div class="eyebrow">KAPITOLA ${String(t.order).padStart(2,'0')} / ${t.minutes} MIN</div><h1>${esc(t.title)}</h1><p>${esc(t.blurb)}</p><div class="lesson-actions">${this.button('Procvičit otázky','start-topic-quiz','primary',t.id,'arrow')}${CALC_SKILLS.some(x=>x.topicId===t.id)?this.button('Počítat příklady','math-topic','outline',t.id,'stats'):''}${this.button('Označit jako prostudované','mark-visited','outline',t.id,'check')}</div></div><div class="reading-layout"><article class="reading"><section><div class="eyebrow">CO BYS MĚL UMĚT</div><ul class="objectives">${t.objectives.map(x=>`<li>${icon('check',17)}${esc(x)}</li>`).join('')}</ul></section>${t.sections.map((s,i)=>`<section class="reading-section"><span class="reading-count">0${i+1}</span><h2>${esc(s.heading)}</h2><p>${esc(s.body)}</p></section>`).join('')}${this.deepDive(t)}<div class="worked-example"><div class="eyebrow">PŘÍKLAD Z PRAXE</div><h2>${esc(t.example.title)}</h2><p class="example-situation">${esc(t.example.situation)}</p><p>${esc(t.example.reasoning)}</p><div class="example-conclusion">${icon('check',20)} <span>${esc(t.example.conclusion)}</span></div></div><div class="pitfall"><div>${icon('alert',20)}<strong>Na co si dát pozor</strong></div><p>${esc(t.pitfall)}</p></div><section class="lesson-cta"><h2>Dokážeš si to vybavit bez nápovědy?</h2><p>Krátký test ukáže, jestli rozumíš principům a umíš je použít.</p>${this.button('Procvičit kapitolu (9 otázek)','start-topic-quiz','primary',t.id,'arrow')}</section></article><aside class="reading-aside"><div class="aside-box"><div class="eyebrow">PODKLADY</div><p>${esc(t.source)}</p></div><div class="aside-box"><div class="eyebrow">STAV UČENÍ</div><strong>${p.reviewed} / ${p.total}</strong><small>pojmů už jsi opakoval(a)</small>${this.progressbar(p.reviewed/p.total*100)}<p class="mini-hint">Pokrok karet se zaznamenává při aktivním vybavování.</p></div></aside></div>`;}
 private homeSignal(){const sum=studySummary(this.content,this.state);const upcoming=sum.examDays===null?'Zadej si termín zápočtu ve studijním plánu.':sum.examDays>=0?`${sum.examDays} dní do zápočtu`:'Termín zápočtu už uplynul';return `<div class="home-signal" role="note"><div class="signal-icon">${icon('spark',24)}</div><div><strong>${sum.mistakes?`${sum.mistakes} otázek čeká na opravu`:'Studijní režim připraven'}</strong><p>${esc(upcoming)} · ${sum.due} splatných karet k opakování</p></div>${this.button('Otevřít plán','nav','outline','coach','arrow')}</div>`;}
 private deepDive(t:Topic){const d=t.deepDive;if(!d)return '';return `<section class="deep-dive"><div class="deep-head"><span class="deep-number">${icon('brain',23)}</span><div><div class="eyebrow">VÝKLAD DO HLOUBKY</div><h2>${esc(d.title)}</h2></div></div><p class="deep-lead">${esc(d.lead)}</p><ol class="thinking-steps">${d.steps.map((step,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><p>${esc(step)}</p></li>`).join('')}</ol><div class="formula-card"><span>VZTAH / PRAVIDLO</span><strong>${esc(d.formula)}</strong></div><div class="challenge"><div class="eyebrow">ZKUS TO NEJPRVE SÁM</div><p>${esc(d.challenge)}</p>${this.challengeRevealed?`<div class="challenge-answer"><strong>Postup a odpověď</strong><p>${esc(d.solution)}</p></div>`:this.button('Ukázat řešení','show-challenge','outline','','check')}</div></section>`;}
 private coach(){const s=studySummary(this.content,this.state);const forecast=dueForecast(this.content,this.state);const highest=s.weak.slice(0,5);const label=s.examDays===null?'Termín zatím není nastavený':s.examDays<0?'Datum je v minulosti':s.examDays===0?'Zápočet máš dnes':`Do zápočtu zbývá ${s.examDays} dní`;return `${this.sectionHead('STUDIJNÍ PLÁN','Dnešní doporučení','Podle výsledků vybíráme slabší témata, nevyřešené chyby a splatné karty. Výběr je pravidlový, nikoli předpověď známky.')}<section class="coach-intro"><div><span class="eyebrow">PŘÍPRAVA NA ZÁPOČET</span><h2>${esc(label)}</h2><p>${s.attempts7?`Za posledních 7 dní jsi odpověděl(a) na ${s.attempts7} otázek. Úspěšnost: ${s.recentAccuracy} %.`:'Začni krátkým procvičováním. Aplikace pak doporučí, ke kterým tématům se vrátit.'}</p></div><label class="date-box">Datum zápočtu <input id="examDate" type="date" value="${this.state.examDate??''}"/></label></section><div class="plan-grid"><article class="plan-tile"><span>01 / OPAKOVAT</span><strong>${s.due}</strong><p>Již naučených pojmů se splatným termínem</p>${this.button('Opakovat karty','start-review','outline','','repeat')}</article><article class="plan-tile"><span>02 / OPRAVIT</span><strong>${s.mistakes}</strong><p>Otázek, na které ses naposledy spletl(a)</p>${this.button('Opravit chyby','start-mistakes','outline','','alert')}</article><article class="plan-tile"><span>03 / ROZŠÍŘIT</span><strong>${s.missing}</strong><p>Kapitol, které ještě nemáš označené jako prostudované</p>${this.button('Otevřít kapitoly','nav','outline','topics','book')}</article></div><div class="info-panel">${icon('brain',26)}<div><strong>Početní dovednosti k procvičení: ${s.mathNeedsWork} z ${CALC_SKILLS.length}</strong><p>Na základě posledních osmi pokusů v každé oblasti. Bez dostatku odpovědí je dovednost zatím označená jako neprocvičená.</p>${this.button('Početní trenažér','nav','outline','math','arrow')}</div></div><div class="coach-two-col"><section class="panel"><div class="eyebrow">DOPORUČENÉ KAPITOLY</div><h2>Čemu se věnovat dál</h2><p>Doporučení zohledňuje poslední výsledky, chyby a neotevřenou látku.</p><div class="priority-list">${highest.map((w,i)=>`<button class="priority-item" data-action="topic" data-value="${w.topic.id}"><span>${String(i+1).padStart(2,'0')}</span><div><strong>${esc(w.topic.title)}</strong><small>${esc(w.reason)}${w.recentAccuracy!==null?` · poslední odpovědi ${w.recentAccuracy} %`:''}</small></div>${icon('chevron',18)}</button>`).join('')}</div>${this.button('Chytrý smíšený test (12 otázek)','start-adaptive','primary','','target')}${this.button('Početní úlohy','nav','outline','math','arrow')}</section><section class="panel"><div class="eyebrow">OPAKOVÁNÍ</div><h2>Výhled na 7 dní</h2><p>Počty vycházejí z aktuálně naplánovaných karet. Nové odpovědi je změní.</p><div class="forecast">${forecast.map((n,i)=>`<div><strong>${n}</strong><span class="forecast-bar"><i style="height:${Math.max(9,Math.round(100*n/Math.max(1,...forecast)))}%"></i></span><small>${i===0?'Dnes':i===1?'Zítra':`${i}. den`}</small></div>`).join('')}</div><p class="coach-tip">${s.mistakes?'Začni opravou chybných odpovědí a potom si dej opakování.':'Pokud nemáš žádné chyby, zkus otázky z více kapitol najednou.'}</p></section></div>`;}
 private mistakes(){const items=unresolvedMistakes(this.content,this.state);const p=weakTopics(this.content,this.state);return `${this.sectionHead('ZPĚTNÁ VAZBA','Moje chyby','Do seznamu patří otázky, u kterých byla tvoje poslední odpověď chybná. Správná odpověď při dalším procvičení chybu odstraní.')}<section class="error-banner"><div><div class="eyebrow">NEVYŘEŠENÉ OTÁZKY</div><h2>${items.length} otázek</h2><p>${items.length?'Vrať se k principu v kapitole. Potom zkus otázku znovu bez nápovědy.':'Momentálně nemáš žádnou nevyřešenou chybu. Zkus smíšený test, aby se ukázala slabší místa.'}</p></div><div class="btn-row">${this.button('Procvičit chyby','start-mistakes','light','','repeat')}${this.button('Smíšený test','start-adaptive','outline','','target')}</div></section><div class="error-list">${items.map(({topic,question})=>`<article class="error-row"><span class="error-tag">${esc(topic.title)}</span><h3>${esc(question.stem)}</h3><details><summary>Zobrazit vysvětlení a správnou odpověď</summary><p><strong>${esc(question.options[question.answer])}</strong></p><p>${esc(question.explanation)}</p></details><button data-action="topic" data-value="${topic.id}" class="text-action">Prostudovat kapitolu ${icon('arrow',16)}</button></article>`).join('')||'<div class="empty-mistakes">Žádné otázky k opravě. Zkus si cvičný zápočet a získáš konkrétnější zpětnou vazbu.</div>'}</div>`;}
 private reviewScreen(){if(this.review){if(this.review.done)return this.reviewFinished();const {entries,index,revealed}=this.review;const e=entries[index];const current=this.state.cards[e.card.id];const total=entries.length;return `<div class="study-center"><div class="study-top"><button class="backlink" data-action="exit-study">← Ukončit opakování</button><div class="study-counter">KARTA ${index+1} / ${total}</div></div>${this.progressbar(index/total*100)}<div class="eyebrow center">${esc(e.topic.title.toUpperCase())}</div><div class="flashcard ${revealed?'revealed':''}"><div class="card-eyebrow">${revealed?'ODPOVĚĎ':'OTÁZKA'}</div><h1>${esc(revealed?e.card.back:e.card.front)}</h1>${!revealed?`<p>Nejdřív si odpověz v hlavě. Potom kartu otoč.</p>`:`<p>Ohodnoť, jak dobře sis odpověď vybavil(a). ${current?'Opakovaný pojem.':'Nový pojem.'}</p>`}</div>${!revealed?`<div class="study-controls">${this.button('Ukázat odpověď','reveal','primary','','arrow')}</div>`:`<div class="rating-controls"><button data-action="rate" data-value="again" class="rate again"><strong>Znovu</strong><span>za 3 minuty</span></button><button data-action="rate" data-value="hard" class="rate hard"><strong>Těžké</strong><span>kratší interval</span></button><button data-action="rate" data-value="good" class="rate good"><strong>Dobré</strong><span>běžné opakování</span></button><button data-action="rate" data-value="easy" class="rate easy"><strong>Snadné</strong><span>delší interval</span></button></div>`}<p class="keyboard-help">Klávesnice: ${revealed?'1–4 ohodnocení':'mezerník = otočit kartu'}</p></div>`;}
  const ready=planReview(this.content,this.state),dueNow=dueCards(this.content,this.state).length,unseen=newCards(this.content,this.state).length;
  return `${this.sectionHead('ROZLOŽENÉ OPAKOVÁNÍ','Trénink paměti','Pojem si nejprve zkus vybavit. Teprve potom zobraz odpověď a upřímně ohodnoť, jak dobře jsi jej znal(a).')}<div class="panel huge-panel"><div class="eyebrow">DNES</div><h2>${dueNow} karet k zopakování</h2><p>K tomu můžeš přidat nové pojmy. Intervaly se plánují podle toho, zda sis odpověď opravdu vybavil(a).</p><div class="review-stat-row"><span><strong>${unseen}</strong> nových pojmů</span><span><strong>${Object.keys(this.state.cards).length}</strong> již procvičených</span></div><div class="btn-row">${this.button(`Spustit ${ready.length} karet`,'start-review','primary','','arrow')}${this.button('Vybrat kapitolu','nav','outline','topics','book')}</div></div><div class="info-panel">${icon('brain',27)}<div><strong>Proč to funguje?</strong><p>Aktivní vybavení a opakování s časovým odstupem obvykle přispívají k trvalejšímu zapamatování lépe než pouhé opakované čtení.</p></div></div>`;
 }
 private reviewFinished(){const data=this.review!;return `<section class="result-hero"><span class="result-icon">${icon('check',42)}</span><div class="eyebrow">HOTOVO</div><h1>Dnešní opakování dokončeno</h1><p>Prošel(a) jsi ${data.entries.length} karet. Další termín každé karty je uložený podle tvého hodnocení.</p><div class="grade-grid">${Object.entries(data.grades).map(([name,count])=>`<div><strong>${count}</strong><span>${name==='again'?'Znovu':name==='hard'?'Těžké':name==='good'?'Dobré':'Snadné'}</span></div>`).join('')}</div><div class="btn-row center-row">${this.button('Přejít na přehled','nav','primary','home','arrow')}${this.button('Ještě procvičovat','start-review','outline','','repeat')}</div></section>`;}
 private exam(){const last=this.state.exams.at(-1);return `${this.sectionHead('SIMULACE ZÁPOČTU','Ověř si znalosti','Smíšené otázky ze všech kapitol. Výsledek získáš až na konci, bez průběžných nápověd.')}<div class="exam-layout"><div class="panel"><div class="eyebrow">NASTAVENÍ TESTU</div><h2>Vyber délku</h2><div class="length-grid"><button class="length-card" data-action="start-exam" data-value="10"><strong>10</strong><span>Rychlá kontrola · cca 5 min</span></button><button class="length-card highlighted" data-action="start-exam" data-value="20"><strong>20</strong><span>Střední test · cca 10 min</span></button><button class="length-card" data-action="start-exam" data-value="30"><strong>30</strong><span>Kompletní procvičení · cca 15 min</span></button></div><p class="muted-note">Otázky jsou promíchané z různých témat. Po dokončení získáš rozbor správných a nesprávných odpovědí.</p></div><aside class="panel slim"><div class="eyebrow">POSLEDNÍ TEST</div>${last?`<div class="big-number">${Math.round(last.correct/last.total*100)} %</div><p>${last.correct} z ${last.total} správně · ${dateLabel(last.at)}</p>`:`<div class="big-number">—</div><p>Dosud žádný cvičný zápočet.</p>`}<hr/><p>Testy jsou pouze orientační. Neodhadují výsledek skutečného zápočtu a neobsahují oficiální otázky UTB.</p></aside></div>`;}
 private quizScreen(){if(!this.quiz)return this.view==='exam'?this.exam():this.topics();const s=this.quiz;
  if(s.done)return this.quizFinished();const entry=s.entries[s.index],q=entry.question;
  const chosen=s.chosen;const after=chosen!==null;const practice=s.kind==='practice';
  return `<div class="study-center quiz-page"><div class="study-top"><button class="backlink" data-action="exit-study">← Ukončit ${practice?'procvičování':'zápočet'}</button><span class="study-counter">OTÁZKA ${s.index+1} / ${s.entries.length}</span></div>${this.progressbar(s.index/s.entries.length*100)}<div class="eyebrow center">${esc(entry.topic.title.toUpperCase())} · ${practice?'PROCVIČOVÁNÍ':'CVIČNÝ ZÁPOČET'}</div><div class="quiz-card"><span class="level-pill">${q.level===3?'NÁROČNĚJŠÍ ÚLOHA':q.level===2?'SOUVISLOSTI':'ZÁKLADY'}</span><h1>${esc(q.stem)}</h1><div class="options" role="group" aria-label="Možnosti odpovědí">${q.options.map((opt,i)=>`<button type="button" class="option ${after&&chosen===i?'selected':''} ${after&&practice&&i===q.answer?'correct':''} ${after&&practice&&chosen===i&&i!==q.answer?'wrong':''}" data-action="answer" data-value="${i}" ${after?'disabled':''}><span>${String.fromCharCode(65+i)}</span><strong>${esc(opt)}</strong>${after&&practice&&i===q.answer?icon('check',20):''}</button>`).join('')}</div>${after&&practice?`<div class="feedback ${chosen===q.answer?'good-feedback':'bad-feedback'}"><strong>${chosen===q.answer?'Správná odpověď':'Správně je '+String.fromCharCode(65+q.answer)+'.'}</strong><p>${esc(q.explanation)}</p></div>`:''}</div><div class="study-controls"><span class="keyboard-help">${after?'Odpověď zaznamenána':'Vyber možnost A–D nebo stiskni 1–4.'}</span>${after?this.button(s.index===s.entries.length-1?'Vyhodnotit':'Další otázka','next-question','primary','','arrow'):''}</div></div>`;}
 private quizFinished(){const s=this.quiz!,right=s.results.filter(x=>x.correct).length,pct=Math.round(right/s.results.length*100);
  const incorrect=s.results.map((a,i)=>({attempt:a,entry:s.entries[i]})).filter(x=>!x.attempt.correct);
  return `<div class="results-page"><div class="result-hero"><span class="result-icon">${icon('target',40)}</span><div class="eyebrow">${s.kind==='exam'?'VÝSLEDEK CVIČNÉHO ZÁPOČTU':'VÝSLEDEK PROCVIČOVÁNÍ'}</div><h1>${pct} % správných odpovědí</h1><p>${right} z ${s.results.length} · ${incorrect.length?`Projdeme ${incorrect.length} chybných odpovědí.`:'Všechny odpovědi byly správně.'}</p><div class="btn-row center-row">${this.button('Zpět na přehled','nav','primary','home','arrow')}${this.button('Opravit chybné otázky','nav','outline','mistakes','alert')}${this.button('Zkusit další test',s.kind==='exam'?'start-exam':'start-topic-quiz','outline',s.kind==='exam'?'20':s.topicId??'', 'repeat')}</div></div>${incorrect.length?`<section class="mistakes"><h2>Otázky k zopakování</h2>${incorrect.map(({entry,attempt})=>`<div class="mistake"><span>${esc(entry.topic.title)}</span><h3>${esc(entry.question.stem)}</h3><p><strong>Správně:</strong> ${esc(entry.question.options[entry.question.answer])}</p><p>${esc(entry.question.explanation)}</p></div>`).join('')}</section>`:`<div class="info-panel">${icon('check',27)}<p>Výborně. Ať znalosti vydrží, vrať se k nim s odstupem v opakování.</p></div>`}</div>`;}
 private newMathProblem(){
  const chosen=this.mathChoice==='adaptive'?suggestedCalcSkill(this.state.mathAttempts??[]):this.mathChoice;
  this.mathProblem=generateCalcProblem(chosen);this.mathHinted=false;this.mathResult=null;this.mathInputError='';
 }
 private submitMathProblem(){
  if(!this.mathProblem||this.mathResult)return;
  const answer=(document.getElementById('mathAnswer') as HTMLInputElement|null)?.value??'';
  const result=gradeCalcProblem(this.mathProblem,answer);
  if(!result.valid){this.mathInputError='Napiš jedno číslo, například 12,5. Jednotku přidávat nemusíš.';const msg=document.getElementById('mathInputError');if(msg)msg.textContent=this.mathInputError;return;}
  this.mathResult=result;
  this.state.mathAttempts??=[];
  this.state.mathAttempts.push({skillId:this.mathProblem.skillId,topicId:this.mathProblem.topicId,correct:result.correct,hinted:this.mathHinted,at:new Date().toISOString(),response:result.value!});
  if(this.state.mathAttempts.length>2500)this.state.mathAttempts=this.state.mathAttempts.slice(-2500);
  this.persist();this.render();
 }
 private mathTrainer(){
  if(!this.mathProblem)this.newMathProblem();
  const p=this.mathProblem!;
  const skill=CALC_SKILLS.find(s=>s.id===p.skillId)!;
  const history=this.state.mathAttempts??[];
  const graded=history.filter(a=>a.correct).length;
  const recent=history.slice(-15);
  const pct=recent.length?Math.round(100*recent.filter(a=>a.correct).length/recent.length):null;
  const last=history.slice(-5).reverse();
  const topic=this.content.topics.find(t=>t.id===p.topicId);
  const result=this.mathResult;
  return `${this.sectionHead('POČETNÍ TRENAŽÉR','Počítej s porozuměním','Proměnlivá zadání, vlastní výpočet a rozebrání postupu. Každá úloha je vytvořený výukový příklad, ne otázka ze skutečného zápočtu.')}
   <section class="calc-summary" aria-label="Výsledky početního tréninku">
    <div><span>Vyřešené pokusy</span><strong>${history.length}</strong></div>
    <div><span>Správné odpovědi</span><strong>${graded}</strong></div>
    <div><span>Posledních 15 pokusů</span><strong>${pct===null?'—':`${pct} %`}</strong></div>
    <div><span>Typy úloh</span><strong>${CALC_SKILLS.length}</strong></div>
   </section>
   <div class="calc-layout"><article class="panel calc-exercise"><div class="calc-exercise-top"><span class="pill">ÚROVEŇ ${skill.level} / 3</span><span class="calc-course-topic">${esc(topic?.title??'Mikroekonomie I')}</span></div>
    <div class="eyebrow">AKTIVNÍ ŘEŠENÍ</div><h2>${esc(p.title)}</h2><p class="calc-question">${esc(p.prompt)}</p>
    <div class="calc-entry"><label for="mathAnswer">Tvůj výsledek <small>(${esc(p.unit)})</small></label>
      <div class="calc-input-line"><input id="mathAnswer" type="text" inputmode="decimal" autocomplete="off" maxlength="32" placeholder="Např. 24,5" ${result?'disabled':''} aria-describedby="mathInputError" />${!result?this.button('Vyhodnotit','math-answer','primary','','check'):''}</div>
      <span id="mathInputError" role="alert" class="calc-error">${esc(this.mathInputError)}</span>
    </div>
    ${!result?`<div class="calc-hint-area">${this.mathHinted?`<p><strong>Jak začít:</strong> ${esc(p.hint)}</p>`:this.button('Potřebuji nápovědu','math-hint','outline','','spark')}</div>`:
     `<div class="calc-feedback ${result.correct?'correct':'incorrect'}" role="status"><strong>${result.correct?'Správně vypočteno.':'Výsledek zatím nesedí.'}</strong><p>Tvá odpověď: ${esc(String(result.value).replace('.',','))} ${esc(p.unit)}. Správně: <strong>${esc(String(p.answer).replace('.',','))} ${esc(p.unit)}</strong>.</p>${this.mathHinted?'<small>Pro řešení byla použita nápověda.</small>':''}</div>
      <div class="calc-solution"><div class="eyebrow">POSTUP ŘEŠENÍ</div><ol>${p.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></div>`}
    <div class="calc-actions">${result?this.button('Další příklad','math-new','primary','','arrow'):this.button('Vygenerovat jiné zadání','math-new','outline','','repeat')}${this.button('Výklad ke kapitole','topic','outline',p.topicId,'book')}</div>
   </article>
   <aside class="calc-aside"><section class="panel calc-selector"><div class="eyebrow">VÝBĚR OBLASTI</div><h3>Co chceš počítat?</h3>
     <label for="mathSkill" class="field-label">Typ úlohy</label><select id="mathSkill" class="calc-select"><option value="adaptive" ${this.mathChoice==='adaptive'?'selected':''}>Doporučené střídání témat</option>${CALC_SKILLS.map(x=>`<option value="${x.id}" ${this.mathChoice===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select>
     <div class="calc-formula"><span>PRAVIDLO / VZOREC</span><strong>${esc(skill.formula)}</strong><p>${esc(skill.summary)}</p></div></section>
     <section class="panel calc-skillboard"><div class="eyebrow">POKROK PODLE TYPU ÚLOHY</div><h3>Co už zvládáš</h3>
       ${CALC_SKILLS.map(item=>{const s=calcSkillProgress(history,item.id);return `<button type="button" class="calc-skill-row ${item.id===skill.id?'selected':''}" data-action="math-select" data-value="${item.id}"><span>${esc(item.title)}</span><small>${s.accuracy===null?'Nové':`${s.accuracy} % · ${s.attempts} pokusů`}</small></button>`;}).join('')}</section>
   </aside></div>
   <div class="info-panel calc-note">${icon('brain',26)}<div><strong>Proč se zadání mění?</strong><p>Nové číselné varianty pomáhají procvičit postup místo zapamatování konkrétní odpovědi. U doporučeného střídání dostávají přednost neprocvičené oblasti a chyby. Hodnocení sleduje až posledních osm pokusů v daném typu úlohy.</p></div></div>
   ${last.length?`<section class="calc-last"><h2>Poslední pokusy</h2><div>${last.map(a=>`<span class="calc-attempt ${a.correct?'correct':'incorrect'}">${a.correct?'✓':'×'} ${esc(CALC_SKILLS.find(s=>s.id===a.skillId)?.title??a.skillId)}</span>`).join('')}</div></section>`:''}`;
 }
 private graphSvg(){
 const x0=60,y0=320,scaleX=(x:number)=>60+(x/140)*600,scaleY=(y:number)=>320-(y/100)*274;
 const d=this.demandShift,s=this.supplyShift,{quantity,price}=marketEquilibrium(d,s);
 const p=(x:number,y:number)=>`${scaleX(x).toFixed(1)},${scaleY(y).toFixed(1)}`;
 return `<svg viewBox="0 0 730 375" role="img" aria-label="Model nabídky, poptávky a jejich rovnováhy"><g stroke="var(--line)" stroke-width="1">${[20,40,60,80].map(v=>`<line x1="60" y1="${scaleY(v)}" x2="665" y2="${scaleY(v)}"/>`).join('')}</g><g stroke="var(--ink-light)" stroke-width="2" fill="none"><path d="M60 33 V320 H672"/><path d="m55 42 5-9 5 9 M663 315 672 320 663 325"/></g><g font-size="13" fill="var(--muted)"><text x="62" y="20">${this.graphModel==='goods'?'Cena (P)':'Mzda (w)'}</text><text x="548" y="361">${this.graphModel==='goods'?'Množství (Q)':'Množství práce (L)'}</text>${[20,40,60,80].map(v=>`<text x="47" y="${scaleY(v)+4}" text-anchor="end">${v}</text>`).join('')}</g><polyline points="${p(0,20+s)} ${p(120,20+s+.4*120)}" stroke="#53a87b" stroke-width="4" fill="none" stroke-linecap="round"/><polyline points="${p(0,80+d)} ${p(120,80+d-.4*120)}" stroke="#ed8b7d" stroke-width="4" fill="none" stroke-linecap="round"/><circle cx="${scaleX(quantity)}" cy="${scaleY(price)}" r="7" fill="var(--ink)" stroke="var(--paper)" stroke-width="3"/><g font-size="17" font-weight="750"><text x="${scaleX(118)+12}" y="${scaleY(20+s+.4*118)-6}" fill="#53a87b">S</text><text x="${scaleX(118)+12}" y="${scaleY(80+d-.4*118)+6}" fill="#ed8b7d">D</text><text x="${scaleX(quantity)+12}" y="${scaleY(price)-13}" fill="var(--ink)">E</text></g><g stroke="var(--muted)" stroke-dasharray="5 5"><line x1="${scaleX(quantity)}" y1="${scaleY(price)}" x2="${scaleX(quantity)}" y2="320"/><line x1="60" y1="${scaleY(price)}" x2="${scaleX(quantity)}" y2="${scaleY(price)}"/></g></svg>`;
 }
 private graphReading(){const {quantity,price}=marketEquilibrium(this.demandShift,this.supplyShift);const kind=this.graphModel==='goods'?'rovnovážná cena':'rovnovážná mzda';return `<div><span>${this.graphModel==='goods'?'Rovnovážné Q':'Rovnovážné L'}</span><strong>${quantity.toFixed(1).replace('.',',')}</strong></div><div><span>${kind}</span><strong>${price.toFixed(1).replace('.',',')}</strong></div><p>Jde o modelové jednotky, nikoliv o reálné české ceny či mzdy.</p>`;}
 private lab(){return `${this.sectionHead('EKONOMICKÁ LABORATOŘ','Rozhýbej nabídku a poptávku','Posunem křivek uvidíš, jak se mění tržní rovnováha. Stejný princip platí pro výrobky i model trhu práce.')}<div class="lab-models"><button class="model-tab ${this.graphModel==='goods'?'active':''}" data-action="graph-model" data-value="goods">Trh výrobků</button><button class="model-tab ${this.graphModel==='labor'?'active':''}" data-action="graph-model" data-value="labor">Trh práce</button></div><div class="lab-layout"><section class="panel lab-chart"><div class="panel-head"><div><div class="eyebrow">INTERAKTIVNÍ MODEL</div><h2>Nabídka S · Poptávka D</h2></div><span class="muted-note">Ilustrační lineární funkce</span></div><div id="marketVisual">${this.graphSvg()}</div><div class="market-reading" id="marketReading">${this.graphReading()}</div></section><aside class="panel lab-controls"><div class="eyebrow">MĚŇ PODMÍNKY</div><h2>Posun křivek</h2><p>Vyšší poptávka posouvá D doprava. Vyšší nabídka posouvá S doprava a dolů.</p><label for="demandShift">Změna poptávky D <strong id="demandShiftValue">${this.demandShift>0?'+':''}${this.demandShift}</strong></label><input id="demandShift" type="range" min="-15" max="15" step="1" value="${this.demandShift}"/><div class="range-ends"><span>pokles</span><span>růst</span></div><label for="supplyShift">Posun nabídky S <strong id="supplyShiftValue">${this.supplyShift>0?'+':''}${this.supplyShift}</strong></label><input id="supplyShift" type="range" min="-15" max="15" step="1" value="${this.supplyShift}"/><div class="range-ends"><span>růst nabídky</span><span>pokles nabídky</span></div>${this.button('Vrátit výchozí stav','graph-reset','outline','','repeat')}</aside></div><div class="info-panel">${icon('brain',26)}<div><strong>Vyzkoušej si scénáře</strong><p>Na trhu práce představuje růst produktivity zaměstnance možný posun poptávky doprava. Automatizace nahrazující určitou práci může způsobit posun poptávky doleva. Jde o dva modelové mechanismy, nikoliv o univerzální prognózu.</p></div></div>`;}
 private glossary(){const collection=allCards(this.content);return `${this.sectionHead('POJMOVNÍK',`Knihovna pojmů`,`Rychlé dohledání definice. Pro trvalé zapamatování doporučuji začít kartami v Opakování.`)}<div class="search-wrap">${icon('search',20)}<input type="search" id="glossarySearch" placeholder="Hledat pojem nebo definici…" aria-label="Hledat pojmy" autocomplete="off"/><span>${collection.length} pojmů</span></div><div class="glossary-grid" id="glossaryCards">${collection.map(({topic,card})=>`<article class="glossary-card" data-search="${esc((card.front+' '+card.back+' '+topic.title).toLocaleLowerCase('cs-CZ'))}"><span>${esc(topic.title)}</span><h2>${esc(card.front)}</h2><p>${esc(card.back)}</p></article>`).join('')}</div><div id="glossaryEmpty" class="empty-search" hidden>Žádný pojem neodpovídá hledání.</div>`;}
 private stats(){const attempts=this.state.attempts,overall=attemptStats(attempts);const exams=this.state.exams;
  return `${this.sectionHead('STUDIJNÍ ANALYTIKA','Jak si vedeš','Zlepšení poznáš podle opakovaných správných odpovědí, nejen podle počtu otevřených lekcí.')}<div class="stats-grid"><div class="stat"><span>Otázky celkem</span><strong>${overall.total}</strong></div><div class="stat"><span>Úspěšnost</span><strong>${overall.total?overall.percentage+' %':'—'}</strong></div><div class="stat"><span>Aktivní pojmy</span><strong>${Object.keys(this.state.cards).length}</strong></div><div class="stat"><span>Početní úlohy</span><strong>${this.state.mathAttempts?.length??0}</strong></div></div><div class="panel stats-panel"><div class="panel-head"><div><div class="eyebrow">PODLE KAPITOL</div><h2>Procvičené oblasti</h2></div></div><div class="topic-performance">${this.content.topics.map(t=>{const p=topicProgress(t,this.state);return `<div class="performance-row"><div class="performance-name"><strong>${esc(t.title)}</strong><small>${p.attempts} odpovědí</small></div><div class="performance-bar">${this.progressbar(p.attempts?p.accuracy:0)}</div><span>${p.attempts?p.accuracy+' %':'—'}</span></div>`}).join('')}</div></div><div class="panel stats-panel"><div class="panel-head"><div class="eyebrow">POSLEDNÍ ZÁPOČTY</div></div>${exams.length?`<div class="exam-history">${exams.slice(-8).reverse().map(x=>`<div><span>${dateLabel(x.at)}</span><strong>${x.correct}/${x.total}</strong><span>${Math.round(x.correct/x.total*100)} %</span></div>`).join('')}</div>`:'<p>Historie je zatím prázdná. Vyzkoušej první cvičný zápočet.</p>'}</div>`;}
 private settings(){return `${this.sectionHead('TVŮJ PROSTOR','Nastavení a zálohy','Všechna data zůstávají v tomto prohlížeči. Žádný účet ani server nejsou potřeba.')}<div class="settings-grid"><section class="panel settings-panel"><div class="eyebrow">DENNÍ CÍL</div><h2>Počet karet v jedné dávce</h2><p>Při každém tréninku dostaneš nejprve karty splatné k opakování a potom nové.</p><div class="setting-row"><input id="dailyGoal" type="range" min="4" max="30" step="2" value="${this.state.dailyGoal}"/><strong id="goalValue">${this.state.dailyGoal} karet</strong></div></section><section class="panel settings-panel"><div class="eyebrow">TERMÍN ZÁPOČTU</div><h2>Datum zkoušky</h2><p>Volitelné datum se používá pouze k plánování učení na tomto zařízení.</p><label for="examDate" class="field-label">Termín zápočtu</label><input class="date-field" type="date" id="examDate" value="${this.state.examDate??''}" /></section><section class="panel settings-panel"><div class="eyebrow">VZHLED</div><h2>Barevné téma</h2><p>Přepni mezi světlým a tmavým režimem podle prostředí, ve kterém se učíš.</p><div class="btn-row">${this.button('Světlý','theme','outline','light','sun')}${this.button('Tmavý','theme','outline','dark','moon')}</div></section><section class="panel settings-panel"><div class="eyebrow">OCHRANA DAT</div><h2>Exportovat pokrok</h2><p>Stáhni si JSON zálohu. Uloží termíny karet, výsledky testů, početní úlohy a historii pokusů.</p>${this.button('Stáhnout zálohu','export','primary','','download')}</section><section class="panel settings-panel"><div class="eyebrow">PŘESUN MEZI ZAŘÍZENÍMI</div><h2>Obnovit pokrok</h2><p>Záloha přepíše dosavadní místní pokrok. Vyber JSON soubor exportovaný z MikroLabu.</p><label class="btn btn-outline file-label" for="importFile">${icon('upload',18)} Nahrát zálohu</label><input id="importFile" type="file" accept=".json,application/json" hidden/></section></div><div class="danger-zone"><div><strong>Vymazat dosavadní pokrok</strong><p>Tato akce je nevratná. Před vymazáním doporučuji exportovat zálohu.</p></div>${this.button('Vymazat data','reset','danger','','alert')}</div><section class="sources-section"><h2>Obsah a zdroje</h2><p>${esc(this.content.disclaimer)}</p><ul>${this.content.sources.map(s=>`<li>${esc(s.label)}</li>`).join('')}</ul><p><strong>Výukové metody:</strong> procvičovací testování a rozložené opakování. Intervaly v této verzi používají transparentní heuristiku podobnou SM-2; nejde o vědecky personalizovaný FSRS model. Používání aplikace nezaručuje výsledek skutečného zápočtu.</p></section>`;}
 private onClick(event:MouseEvent){const target=event.target as HTMLElement|null;const node=target?.closest<HTMLElement>('[data-action]');if(!node)return;
  event.preventDefault();const a=node.dataset.action||'',value=node.dataset.value||'';
  if(a==='math-topic'){const item=CALC_SKILLS.find(s=>s.topicId===value);if(item){this.mathChoice=item.id;this.newMathProblem();this.nav('math');}return;}
  if(a==='math-select'){const selected=CALC_SKILLS.find(s=>s.id===value);if(selected){this.mathChoice=selected.id;this.newMathProblem();this.render();}return;}
  if(a==='math-new'){this.newMathProblem();this.render();return;}
  if(a==='math-hint'){this.mathHinted=true;this.render();return;}
  if(a==='math-answer'){this.submitMathProblem();return;}
  if(a==='show-challenge'){this.challengeRevealed=true;this.render();return;}
  if(a==='start-adaptive'){const entries=adaptiveQuestions(this.content,this.state,Math.min(12,allQuestions(this.content).length));this.quiz={kind:'practice',entries,index:0,chosen:null,results:[],done:false,topicId:null};this.nav('practice');return;}
  if(a==='start-mistakes'){const errors=unresolvedMistakes(this.content,this.state);if(!errors.length){this.notice='Zatím nemáš žádné nevyřešené chyby.';this.render();return;}const entries=errors.slice(0,20);this.quiz={kind:'practice',entries,index:0,chosen:null,results:[],done:false,topicId:null};this.nav('practice');return;}
  if(a==='menu'){this.sidebarOpen=!this.sidebarOpen;this.render();return;}
  if(a==='nav'){if(value==='math'&&!this.mathProblem)this.newMathProblem();if(value==='review')this.review=null;if(value==='exam')this.quiz=null;this.nav(value as View);return;}
  if(a==='topic'){this.nav('lesson',value);return;}
  if(a==='mark-visited'){if(!this.state.visitedTopics.includes(value))this.state.visitedTopics.push(value);this.persist();this.render();return;}
  if(a==='start-review'){const entries=planReview(this.content,this.state);this.review={entries,index:0,revealed:false,done:entries.length===0,grades:{again:0,hard:0,good:0,easy:0}};this.nav('review');return;}
  if(a==='reveal'&&this.review){this.review.revealed=true;this.render();return;}
  if(a==='rate'&&this.review&&this.review.revealed){const rating=value as 'again'|'hard'|'good'|'easy';if(!['again','hard','good','easy'].includes(rating))return;const e=this.review.entries[this.review.index];this.state.cards[e.card.id]=nextReview(this.state.cards[e.card.id],e.card.id,e.topic.id,rating);this.review.grades[rating]++;const key=localDayKey(new Date());if(!this.state.reviewDays.includes(key))this.state.reviewDays.push(key);this.review.index++;this.review.revealed=false;if(this.review.index>=this.review.entries.length)this.review.done=true;this.persist();this.render();return;}
  if(a==='start-topic-quiz'){const t=this.content.topics.find(x=>x.id===value);if(!t)return;this.quiz={kind:'practice',entries:pickQuestions(this.content,9,value),index:0,chosen:null,results:[],done:false,topicId:value};this.nav('practice');return;}
  if(a==='start-exam'){const count=Math.max(1,Math.min(30,Number(value)||20));this.quiz={kind:'exam',entries:pickQuestions(this.content,count,null),index:0,chosen:null,results:[],done:false,topicId:null};this.nav('exam');return;}
  if(a==='answer'){this.answer(Number(value));return;}
  if(a==='next-question'){this.nextQuestion();return;}
  if(a==='exit-study'){this.review=null;this.quiz=null;this.nav('home');return;}
  if(a==='graph-model'&&(value==='goods'||value==='labor')){this.graphModel=value;this.render();return;}
  if(a==='graph-reset'){this.demandShift=0;this.supplyShift=0;this.render();return;}
  if(a==='theme'&&(value==='dark'||value==='light')){this.state.preference=value;this.persist();this.render();return;}
  if(a==='export'){const blob=new Blob([backupJson(this.state)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`mikrolab-zaloha-${new Date().toISOString().slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
  if(a==='reset'){if(!window.confirm('Opravdu vymazat veškerý pokrok uložený na tomto zařízení?'))return;this.state={...initialState(),preference:this.state.preference};this.persist();this.notice='Místní pokrok byl vymazán.';this.nav('settings');this.notice='Místní pokrok byl vymazán.';this.render();return;}
 }
 private answer(choice:number){const s=this.quiz;if(!s||s.done||s.chosen!==null||choice<0||choice>3)return;const {topic,question}=s.entries[s.index];s.chosen=choice;s.results.push(recordedAttempt(question.id,topic.id,choice===question.answer,s.kind));if(s.kind==='practice'){this.state.attempts.push(s.results.at(-1)!);this.persist();}this.render();}
 private nextQuestion(){const s=this.quiz;if(!s||s.chosen===null||s.done)return;if(s.index===s.entries.length-1){s.done=true;if(s.kind==='exam'){this.state.attempts.push(...s.results);this.state.exams.push(examinationResult(s.results));}else if(s.topicId&&!this.state.visitedTopics.includes(s.topicId)){this.state.visitedTopics.push(s.topicId);}this.persist();this.render();return;}s.index++;s.chosen=null;this.render();}
 private onKey(e:KeyboardEvent){if(this.view==='math'&&e.key==='Enter'&&(e.target as HTMLElement|null)?.id==='mathAnswer'){e.preventDefault();this.submitMathProblem();return;}const el=e.target as HTMLElement|null;if(el&&(el.matches('input, textarea, select')||el.isContentEditable)||e.ctrlKey||e.metaKey||e.altKey)return;
  if((this.view==='practice'||this.view==='exam')&&this.quiz&&!this.quiz.done){if(/^[1-4]$/.test(e.key)){e.preventDefault();this.answer(Number(e.key)-1);}else if(e.key==='Enter'&&this.quiz.chosen!==null){e.preventDefault();this.nextQuestion();}}
  if(this.view==='review'&&this.review&&!this.review.done){if(e.code==='Space'&&!this.review.revealed){e.preventDefault();this.review.revealed=true;this.render();}else if(this.review.revealed&&/^[1-4]$/.test(e.key)){e.preventDefault();const names=['again','hard','good','easy'];const btn=document.querySelector<HTMLElement>(`[data-action="rate"][data-value="${names[Number(e.key)-1]}"]`);btn?.click();}}
 }
 private onInput(e:Event){const el=e.target as HTMLInputElement;if(el.id==='glossarySearch'){
   const term=el.value.toLocaleLowerCase('cs-CZ').trim();let visible=0;document.querySelectorAll<HTMLElement>('.glossary-card').forEach(x=>{const show=(x.dataset.search||'').includes(term);x.hidden=!show;if(show)visible++;});const empty=document.querySelector<HTMLElement>('#glossaryEmpty');if(empty)empty.hidden=visible!==0;
  }else if(el.id==='demandShift'||el.id==='supplyShift'){const n=Math.max(-15,Math.min(15,Number(el.value)));if(el.id==='demandShift')this.demandShift=n;else this.supplyShift=n;const visual=document.querySelector('#marketVisual');if(visual)visual.innerHTML=this.graphSvg();const output=document.querySelector('#marketReading');if(output)output.innerHTML=this.graphReading();const number=document.querySelector('#'+el.id+'Value');if(number)number.textContent=n>0?'+'+n:String(n);
  }else if(el.id==='dailyGoal'){const output=document.querySelector('#goalValue');if(output)output.textContent=`${el.value} karet`;}
 }
 private async onChange(e:Event){const el=e.target as HTMLInputElement;
  if(el.id==='mathSkill'){const v=el.value;this.mathChoice=v==='adaptive'?'adaptive':CALC_SKILLS.find(s=>s.id===v)?.id??'adaptive';this.newMathProblem();this.render();return;}
  if(el.id==='examDate'){this.state.examDate=el.value||undefined;this.persist();}
  if(el.id==='dailyGoal'){this.state.dailyGoal=Math.max(4,Math.min(30,Number(el.value)));this.persist();}
  if(el.id==='importFile'&&el.files?.[0]){try{if(el.files[0].size>2_000_000)throw new Error('Záloha je příliš velká (max. 2 MB).');const text=await el.files[0].text();const state=parseBackup(text,this.content);if(!window.confirm('Nahraná záloha nahradí aktuální pokrok v tomto prohlížeči. Pokračovat?'))return;this.state=state;this.persist();this.notice='Záloha byla obnovena.';this.render();}catch(err){this.notice=err instanceof Error?err.message:'Soubor se nepodařilo načíst.';this.render();}}
 }
}
